use num_traits::{One, Zero};

fn fibonacci(n: usize) -> BigUint {
    if n == 0 {
        return BigUint::from(0u32);
    } else if n == 1 {
        return BigUint::from(1u32);
    }

    let sqrt_5 = BigUint::from(5u32).sqrt();
    let phi = (BigUint::one() + sqrt_5) / BigUint::from(2u32);
    let psi = (BigUint::one() - sqrt_5) / BigUint::from(2u32);

    (phi.pow(n as u32) - psi.pow(n as u32)) / sqrt_5
